import { _useId } from '../../core/hooks/useId.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DOMAttributes, DOMProps } from '../../core/types/dom.js';

/** @internal */
export interface _AriaDialogProps extends DOMProps, AriaLabelingProps {
  /**
   * The accessibility role for the dialog.
   * @defaultValue 'dialog'
   */
  role?: 'dialog' | 'alertdialog';
}

/** @internal */
export interface _DialogAria {
  /** Props for the dialog container element. */
  dialogProps: DOMAttributes;

  /** Props for the dialog title element. */
  titleProps: DOMAttributes;
}

/**
 * Provides the behavior and accessibility implementation for a dialog component.
 * A dialog is an overlay shown above other content in an application.
 * @internal
 */
export function _useDialog(props: _AriaDialogProps): _DialogAria {
  const {
    role = 'dialog',
    'aria-labelledby': ariaLabelledBy,
    ...remainingProps
  } = props;
  const uniqueId = _useId();

  const titleId: string | undefined = props['aria-label']
    ? undefined
    : uniqueId;

  return {
    dialogProps: {
      role,
      tabIndex: -1,
      'aria-labelledby': ariaLabelledBy || titleId,
      ...remainingProps,
    },
    titleProps: {
      id: titleId,
    },
  };
}
